// 1 · primitives — private, never imported by product code
$gray-900: #141414;
$lime-400: #d9ff57;

// 2 · semantic aliases — the public API
:root {
  --fg-default: #{$gray-900};
  --accent-interactive: #{$lime-400};
  --control-gap: 1rem;
}

// 3 · component tokens — the override point
forge-button {
  --button-focus-ring: var(--accent-interactive);
  --button-gap: 0.5rem;
}
